-- MemeRush schema for Cloudflare D1 (SQLite). Port of supabase/migrations/0001~0003.
-- ids are generated by the app (crypto.randomUUID); timestamps are ISO-8601 strings; arrays/json are stored as TEXT (JSON).
-- Postgres-only parts removed: gen_random_uuid(), int[] / jsonb, RLS (all access goes through API routes),
-- storage bucket (videos route is not in the public build), rpc attempt_server_elapsed_ms (computed in app code from started_at).

create table players (
  id text primary key,
  session_token text not null unique,
  nickname text not null check (length(nickname) between 1 and 20),
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create table leagues (
  id text primary key,
  owner_id text not null unique references players(id),
  invite_token text not null unique,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create table league_members (
  league_id text not null references leagues(id),
  player_id text not null references players(id),
  joined_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  primary key (league_id, player_id)
);

create table referrals (
  id text primary key,
  challenge_id text not null,
  source_player_id text not null references players(id),
  league_id text references leagues(id),
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create table attempts (
  id text primary key,
  player_id text not null references players(id),
  challenge_id text not null,
  referral_id text references referrals(id),
  started_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  finished_at text,
  round_elapsed_ms text,   -- JSON array
  round_error_ms text,     -- JSON array
  error_ms integer,
  outcome text,
  outcome_variant text,
  video_path text
);

create index attempts_ranking on attempts (challenge_id, error_ms) where error_ms is not null;
create index attempts_player on attempts (player_id, challenge_id);

-- Best finished attempt per (player, challenge): lowest error_ms, earliest finish on ties.
create view best_attempts as
select id, player_id, challenge_id, error_ms, finished_at, round_elapsed_ms, round_error_ms,
       outcome, outcome_variant, video_path, nickname
from (
  select a.id, a.player_id, a.challenge_id, a.error_ms, a.finished_at, a.round_elapsed_ms, a.round_error_ms,
         a.outcome, a.outcome_variant, a.video_path, p.nickname,
         row_number() over (partition by a.player_id, a.challenge_id order by a.error_ms, a.finished_at) as rn
  from attempts a
  join players p on p.id = a.player_id
  where a.error_ms is not null
)
where rn = 1;

create table events (
  id integer primary key autoincrement,
  type text not null,
  challenge_id text,
  player_id text,
  referral_id text,
  meta text,               -- JSON
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- Email CTA subscribers. Unsubscribe deletes the row immediately (privacy draft); unsubscribed_at is kept for schema parity only.
create table email_subscribers (
  id text primary key,
  email text not null check (length(email) <= 254),
  lang text not null default 'en',
  source text,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  unsubscribed_at text
);
create unique index email_subscribers_email_key on email_subscribers (lower(email));
